export const hasCantiqueAudio = (cantique) => {
  if (!cantique) return false
  return Boolean(
    cantique.audioUrl ||
    cantique.hasAudio ||
    cantique.audio
  )
}

export const resolveCantiqueAudioUrl = (audioUrl) => {
  if (!audioUrl || typeof audioUrl !== 'string') return null
  if (
    audioUrl.startsWith('http://') ||
    audioUrl.startsWith('https://') ||
    audioUrl.startsWith('blob:') ||
    audioUrl.startsWith('data:')
  ) {
    return audioUrl
  }
  if (audioUrl.startsWith('/api/')) {
    return audioUrl
  }
  if (audioUrl.startsWith('/')) {
    return audioUrl
  }
  return audioUrl
}

export const getCantiqueAudioUrl = (cantique) => {
  if (!hasCantiqueAudio(cantique)) return null
  return resolveCantiqueAudioUrl(cantique.audioUrl)
}
