import React, { useState, useContext } from 'react'
import { Search, List, TableProperties, PanelLeftClose, Funnel } from 'lucide-react';
import { CantiqueContextAPI } from '../Context/CantiqueContext';

const SidebardSearch = () => {
    const { searchTerm, setSearchTerm, viewMode, setViewMode } = useContext(CantiqueContextAPI);
    const [isSearchOpen, setIsSearchOpen] = useState(false);

    const toggleSearch = () => {
        setIsSearchOpen(!isSearchOpen);
    };

    const handleSearchChange = (e) => {
        setSearchTerm(e.target.value);
    };

    const handleSearchClear = () => {
        setSearchTerm('');
    };

    return (
        <div className="sidebardSearch">
            <div className="sidebardSearch__container">
                <div className="sidebardSearch__top">
                    <div className="sidebardSearch__top__left">
                        <h3 className="sidebardSearch__top__title">
                            Cantiques
                        </h3>
                        <div className="sidebardSearch__top__icon__search">
                            <span
                                className={`${isSearchOpen ? 'is-open' : ''}`}
                                onClick={toggleSearch}
                                role="button"
                                tabIndex={0}
                                aria-label="Toggle search"
                            >
                                <Search size={14} className='sidebardSearch__icon' />
                            </span>
                        </div>
                    </div>
                    {/* Du coté Right */}
                    <div className="sidebardSearch__top__right">
                        <ul className="sidebardSearch__top__right__list">
                            {/* Par default la liste s'affiche en liste */}
                            <li
                            className={`sidebardSearch__top__right__item ${viewMode === 'list' ? 'active' : ''}`}
                            onClick={() => setViewMode('list')}
                            role="button"
                            tabIndex={0}
                        >
                             <List size={14} className='sidebardSearch__top__right__item__icon' />
                        </li>
                        {/* Bouton de switching version affichage par numerotation du cantique */}
                        <li
                            className={`sidebardSearch__top__right__item ${viewMode === 'number' ? 'active' : ''}`}
                            onClick={() => setViewMode('number')}
                            role="button"
                            tabIndex={0}
                        >
                            <TableProperties size={14} className='sidebardSearch__top__right__item__icon' />
                        </li>
                        </ul>
                    </div>
                </div>
                {/*  Input Search  */}
                <div className={`sidebardSearch__inputs ${isSearchOpen ? 'is-open' : ''}`}>
                    <input 
                        type="search" 
                        className="sidebardSearch__inputs__search"
                        placeholder='Rechercher (Titre/paroles...)...'
                        value={searchTerm}
                        onChange={handleSearchChange}
                    />
                    {searchTerm && (
                        <button 
                            onClick={handleSearchClear}
                            style={{
                                position: 'absolute',
                                right: '10px',
                                background: 'none',
                                border: 'none',
                                cursor: 'pointer',
                                color: '#999'
                            }}
                        >
                            ✕
                        </button>
                    )}
                </div>
            </div>
        </div>
    )
}

export default SidebardSearch