import React, { createContext, useState, useEffect, useRef } from 'react'
import { useNavigate, useLocation } from 'react-router-dom'
import { toast } from 'react-toastify';
import * as Api from '../Services/Api'

export const CantiqueContextAPI = createContext();

const CantiqueContext = ({ children }) => {
  const [cantiques, setCantiques] = useState([]);
  // store the full language objects we get from the API. each entry
  // contains an id and name. some components (admin) must know the id
  // so we can't just keep strings here.
  const [languages, setLanguages] = useState([]); // array of {id,name}
  const [selectedCantique, setSelectedCantique] = useState(null);
  // tracks whether we're currently loading details for a cantique
  const [loading, setLoading] = useState(false);
  // id of the cantique we're currently fetching (used to show a spinner next to the title)
  const [pendingCantiqueId, setPendingCantiqueId] = useState(null);
  
  const navigate = useNavigate();
  const location = useLocation();
  const inactivityTimer = useRef(null);

  const resetInactivity = () => {
    if (inactivityTimer.current) clearTimeout(inactivityTimer.current);
    inactivityTimer.current = setTimeout(() => {
      // on prolonged inactivity go back to home (croix) and clear selection
      setSelectedCantique(null);
      navigate('/home');
    }, 20 * 60 * 1000); // 20 minutes
  };
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedLanguage, setSelectedLanguage] = useState(null);
  // UI state: whether the sidebar (mobile) is open
  const [sidebarOpen, setSidebarOpen] = useState(false);
  // view style for the cantique list, either 'list' or 'number'
  // persist user's preference in localStorage so it survives reloads
  const [viewMode, setViewMode] = useState(() => {
    try {
      const saved = localStorage.getItem('viewMode');
      return saved === 'number' ? 'number' : 'list';
    } catch (_err) {
      return 'list';
    }
  });
  const [duplicateCantique, setDuplicateCantique] = useState(null);

  // keep localStorage in sync with the state
  useEffect(() => {
    try {
      localStorage.setItem('viewMode', viewMode);
    } catch (_err) {
      // ignore
    }
  }, [viewMode]);

  // Function to normalize text for search (remove accents, lowercase, allow special chars)
  const normalizeText = (text) => {
    return text
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '') // remove accents
      .replace(/[^a-z0-9\s&]/g, ' ') // replace special chars with space, keep & and letters/numbers/spaces
      .replace(/\s+/g, ' ')
      .trim();
  };

  /**
   * Select a cantique by id. When an id is provided we enter a brief
   * "loading" state before the details are finally set in order to give
   * the user a small animation/feedback when they tap on a title.
   */
  useEffect(() => {
    // fetch fresh list from API
    Api.fetchCantiques()
      .then(res => {
        const normalized = res.data.map(c => ({
          ...c,
          id: c._id // keep old code working
        }));
        setCantiques(normalized);
      })
      .catch(err => console.error('load cantiques', err));

    // also load languages
    Api.fetchLangues()
      .then(res => {
        // keep objects; sort by name for consistent ordering
        setLanguages(res.data
          .map(l => ({ id: l._id, name: l.name }))
          .sort((a, b) => a.name.localeCompare(b.name))
        );
      })
      .catch(err => console.error('load langues', err));

    // start inactivity watcher
    const events = ['click', 'keydown', 'mousemove', 'touchstart'];
    events.forEach(evt => window.addEventListener(evt, resetInactivity));
    resetInactivity();
    return () => {
      events.forEach(evt => window.removeEventListener(evt, resetInactivity));
      if (inactivityTimer.current) clearTimeout(inactivityTimer.current);
    };
  }, []);

  const selectCantique = (id) => {
    resetInactivity();
    // if null explicitly requested, clear selection and navigate home
    if (id === null) {
      setSelectedCantique(null);
      setPendingCantiqueId(null);
      navigate('/');
      return;
    }

    // toggle off if clicking the currently selected item.
    if (selectedCantique?.id === id) {
      setSelectedCantique(null);
      setPendingCantiqueId(null);
      navigate('/');
      return;
    }

    const cantique = cantiques.find(c => c.id === id || c._id === id);
    if (cantique) {
      setLoading(true);
      setPendingCantiqueId(id);
      // simulate a small delay so the spinner is visible
      setTimeout(() => {
        setSelectedCantique(cantique);
        setLoading(false);
        setPendingCantiqueId(null);
        navigate(`/cantiques/${id}`);
      }, 400);
    }
    // on mobile, close the sidebar immediately when selecting a cantique
    if (typeof window !== 'undefined' && window.innerWidth <= 1000) {
      setSidebarOpen(false);
    }
    resetInactivity();
  };

  // Modifier un cantique existant
  const modifyCantique = async (id, updatedData) => {
    try {
      const res = await Api.updateCantique(id, updatedData);
      const updated = { ...res.data, id: res.data._id };
      setCantiques(cantiques.map(c =>
        c._id === id || c.id === id ? updated : c
      ));
      if (selectedCantique && (selectedCantique.id === id || selectedCantique._id === id)) {
        setSelectedCantique(updated);
      }
      return true;
    } catch (err) {
      console.error('update cantique', err);
      toast.error(`Erreur lors de la modification du cantique : ${err.response?.data?.message || err.message}`);
      return false;
    }
  };

  // Supprimer un cantique
  const deleteCantique = async (id) => {
    try {
      await Api.deleteCantique(id);
      setCantiques(cantiques.filter(c => c._id !== id && c.id !== id));
      if (selectedCantique && (selectedCantique._id === id || selectedCantique.id === id)) {
        setSelectedCantique(null);
      }
    } catch (err) {
      console.error('delete cantique', err);
      toast.error(`Erreur lors de la suppression du cantique : ${err.response?.data?.message || err.message}`);
    }
  };

  // Ajouter un nouveau cantique
  const addCantique = async (newCantique) => {
    // Check for duplicate title
    const existing = cantiques.find(c => c.title.toLowerCase() === newCantique.title.toLowerCase());
    if (existing) {
      setDuplicateCantique(existing);
      return false; // Indicate not added
    }
    try {
      const res = await Api.createCantique(newCantique);
      setCantiques([...cantiques, { ...res.data, id: res.data._id }]);
      return true; // Indicate added
    } catch (err) {
      console.error('create cantique', err);
      toast.error(`Erreur lors de la création du cantique : ${err.response?.data?.message || err.message}`);
      return false;
    }
  };

  // Filtrer les cantiques basé sur la recherche et la langue sélectionnée
  const filteredCantiques = cantiques.filter(c => {
    const matchesLanguage = selectedLanguage === null || c.langue === selectedLanguage;
    const normalizedSearch = normalizeText(searchTerm);
    const searchWords = normalizedSearch.split(/\s+/).filter(word => word.length > 0);
    const matchesSearch = searchTerm === '' || 
      searchWords.some(word => 
        normalizeText(c.title).includes(word) ||
        c.couplets?.some(couplet => normalizeText(couplet.text).includes(word))
      );
    
    return matchesLanguage && matchesSearch;
  });

  const logout = () => {
    localStorage.removeItem('token');
    navigate('/login?logout=true');
  };

  const value = {
    // Original data
    selectedCantique,
    selectCantique,
    allCantiques: cantiques,
    filteredCantiques,
    loading,
    pendingCantiqueId,
    
    // Modification functions
    modifyCantique,
    deleteCantique,
    addCantique,
    
    // Search and filter state
    searchTerm,
    setSearchTerm,
    selectedLanguage,
    setSelectedLanguage,
    // Sidebar control for mobile
    sidebarOpen,
    setSidebarOpen,
    // list display mode ('list' or 'number')
    viewMode,
    setViewMode,
    
    // Duplicate modal
    duplicateCantique,
    setDuplicateCantique,
    
    // Authentication helpers
    logout,

    // Get unique languages (from API list)
    availableLanguages: languages,          // array of {id,name}
    // function to refresh languages list (can be called by other components)
    refreshLanguages: async () => {
      try {
        const res = await Api.fetchLangues();
        setLanguages(res.data
          .map(l => ({ id: l._id, name: l.name }))
          .sort((a, b) => a.name.localeCompare(b.name))
        );
      } catch (e) {
        console.error('refresh languages', e);
      }
    }
  };

  // keep the URL and selection in sync - also handle direct link / refresh
  useEffect(() => {
    const path = location.pathname;
    if (path.startsWith('/cantiques/')) {
      const id = path.split('/')[2];
      const cantique = cantiques.find(c => c.id === id || c._id === id);
      if (cantique) {
        setSelectedCantique(cantique);
      }
    } else {
      setSelectedCantique(null);
    }
    resetInactivity();
  }, [location.pathname, cantiques]);

  return (
    <CantiqueContextAPI.Provider value={value}>
      {children}
    </CantiqueContextAPI.Provider>
  );
}

export default CantiqueContext