import React from 'react'
import { X, AlertCircle, Trash2 } from 'lucide-react'

const ConfirmDeleteModal = ({ isOpen, onClose, cantiqueName, onConfirm }) => {
  if (!isOpen) return null

  const handleBackdropClick = (e) => {
    if (e.target === e.currentTarget) {
      onClose()
    }
  }

  return (
    <div className="confirmDeleteModal" onClick={handleBackdropClick}>
      <div className="confirmDeleteModal__container">
        <button className="confirmDeleteModal__close" onClick={onClose}>
          <X size={24} />
        </button>

        <div className="confirmDeleteModal__icon">
          <AlertCircle size={48} />
        </div>

        <h2 className="confirmDeleteModal__title">Confirmer la suppression</h2>
        
        <p className="confirmDeleteModal__message">
          Êtes-vous sûr de vouloir supprimer le cantique <strong>"{cantiqueName}"</strong> ?
        </p>
        
        <p className="confirmDeleteModal__warning">
          Cette action est irréversible et supprimera définitivement le cantique et tous ses contenus.
        </p>

        <div className="confirmDeleteModal__actions">
          <button
            className="confirmDeleteModal__btn confirmDeleteModal__btn--cancel"
            onClick={onClose}
          >
            Annuler
          </button>
          <button
            className="confirmDeleteModal__btn confirmDeleteModal__btn--delete"
            onClick={() => {
              onConfirm()
              onClose()
            }}
          >
            <Trash2 size={16} />
            <span>Supprimer</span>
          </button>
        </div>
      </div>
    </div>
  )
}

export default ConfirmDeleteModal
