import React from 'react'
import Home from './Home'
import HomeDisplayCantique from './HomeDisplayCantique'

import { useContext } from 'react';
import { CantiqueContextAPI } from '../Context/CantiqueContext';

const Display = () => {
  const { selectedCantique } = useContext(CantiqueContextAPI);

  return (
    <div className="display">
        <div className="display__container">
               {/* show homepage if nothing has been selected yet */}
               {selectedCantique ? <HomeDisplayCantique /> : <Home />}
            </div>
    </div>
  )
}

export default Display