import React, { useContext } from 'react'
import { Music4 } from 'lucide-react';
import { CantiqueContextAPI } from '../Context/CantiqueContext';
import { hasCantiqueAudio } from '../utils/cantiqueAudio';

const CantiquesList = () => {
  const { filteredCantiques, selectCantique, selectedCantique, loading, pendingCantiqueId, setSidebarOpen, viewMode } = useContext(CantiqueContextAPI);

  const handleSelectCantique = (id) => {
    // toggle off if clicking the currently selected item.
    if (selectedCantique?.id === id) {
      selectCantique(null);
    } else {
      selectCantique(id);
      // on mobile, close the sidebar immediately when selecting a cantique
      if (typeof window !== 'undefined' && window.innerWidth <= 1000) {
        setSidebarOpen(false);
      }
    }
  };

  return (
    <div className={`cantiqueList ${viewMode === 'number' ? 'cantiqueList--number' : ''}`}>
         <div className="cantiqueList__container">
           {filteredCantiques.length > 0 ? (
             filteredCantiques.map((cantique) => (
               <div 
                 key={cantique.id}
                 className={`cantiqueList__cantique ${selectedCantique?.id === cantique.id ? 'active' : ''}`}
                 onClick={() => handleSelectCantique(cantique.id)}
                 role="button"
                 tabIndex={0}
               >
                <div className="cantiqueList__cantique__left">
                  <div className="cantiqueList__number">{cantique.number || '-'}</div>
                  <div className="cantiqueList__title">{cantique.title}</div>
                  <div className="cantiqueList__langue" style={{ fontSize: '0.75em', color: '#999', marginTop: '0.2em',
                    marginLeft: '0.3em'
                   }}>
                    {cantique.langue}
                  </div>
                </div>

                 {(pendingCantiqueId === cantique.id && loading) || hasCantiqueAudio(cantique) ? (
                   <div className="cantiqueList__icon">
                     {pendingCantiqueId === cantique.id && loading ? (
                       <div className="loading-spinner" style={{width: '1.2em', height: '1.2em', borderWidth: '2px'}} />
                     ) : (
                       <Music4 size={15} className="cantiqueList__icon__music" />
                     )}
                   </div>
                 ) : null}
               </div>
             ))
           ) : (
             <div style={{ padding: '2rem', textAlign: 'center', color: '#999' }}>
               Aucun cantique trouvé
             </div>
           )}
         </div>
     </div>
  )
}

export default CantiquesList