import React, { useContext } from 'react'
import { CantiqueContextAPI } from '../Context/CantiqueContext';

const CantiquesDetails = () => {
  const { selectedCantique, loading } = useContext(CantiqueContextAPI);

  // display a simple spinner during the small loading delay
  if (loading) {
    return (
      <div className="cantiquesDetails">
        <div className="cantiquesDetails__container">
          <div className="loading-spinner" />
        </div>
      </div>
    );
  }

  if (!selectedCantique) {
    return (
      <div className="cantiquesDetails">
        <div className="cantiquesDetails__container">
          <p>Sélectionnez un cantique</p>
        </div>
      </div>
    );
  }

  return (
    <div className="cantiquesDetails">
        <div className="cantiquesDetails__container">
          {selectedCantique.couplets.map((couplet, index) => (
            <React.Fragment key={index}>
              <div className="cantiquesDetails__couplet">
                <div className="cantiquesDetails__couplet__number">{(couplet.numero ?? couplet.number)}.</div>
                <div className="cantiquesDetails__couplet__text">
                  <span>{couplet.text}</span>
                </div>
              </div>

              {/* Afficher refrain après le premier couplet s'il existe */}
              {index === 0 && selectedCantique.refrain && (
                <div className="cantiquesDetails__choeur__refrain">
                  <span>Refrain:</span>
                  <div className="cantiquesDetails__choeur__text">
                    {selectedCantique.refrain.text} 
                  </div>
                </div>
              )}

              {/* Afficher semi-choeur après le premier couplet s'il existe */}
              {index === 0 && selectedCantique.semiChoeur && (
                <div className="cantiquesDetails__choeur">
                  <span>*</span>
                  <div className="cantiquesDetails__choeur__text">
                    {selectedCantique.semiChoeur.text}
                  </div>
                </div>
              )}
            </React.Fragment>
          ))}
        </div>
    </div>
  )
}

export default CantiquesDetails