import React, { useContext, useState, useEffect } from 'react'
import { X, ZoomIn, ZoomOut } from 'lucide-react'
import { CantiqueContextAPI } from '../Context/CantiqueContext'

const Projections = ({ isOpen, onClose }) => {
  const { selectedCantique } = useContext(CantiqueContextAPI);
  const [fontSize, setFontSize] = useState(28);
  const [coupletIndex, setCoupletIndex] = useState(0);

  useEffect(() => {
    if (isOpen && selectedCantique) {
      setFontSize(28);
      setCoupletIndex(0);
    }
  }, [isOpen, selectedCantique]);

  if (!isOpen || !selectedCantique) return null;

  const increase = () => setFontSize(s => Math.min(80, s + 4));
  const decrease = () => setFontSize(s => Math.max(12, s - 4));

  const prevCouplet = () => setCoupletIndex(i => Math.max(0, i - 1));
  const nextCouplet = () => setCoupletIndex(i => Math.min(selectedCantique.couplets.length - 1, i + 1));

  // backdrop no longer closes projection; only close button

  return (
    <div className="projectionOverlay">
      <div className="projectionContainer">
        <button className="projectionClose" onClick={onClose}>
          <X size={32} />
        </button>

        <div className="projectionControls">
          <button onClick={decrease}><ZoomOut size={24} /></button>
          <button onClick={increase}><ZoomIn size={24} /></button>
        </div>

        <h1 className="projectionTitle" style={{ fontSize: fontSize + 8 }}>{selectedCantique.title}</h1>
        <div className="projectionBody" style={{ fontSize }}>
          {/* show only current couplet */}
          {selectedCantique.couplets[coupletIndex] && (
            <p className="projectionParagraph">
              <strong>{(selectedCantique.couplets[coupletIndex].numero ?? selectedCantique.couplets[coupletIndex].number)}.</strong> {selectedCantique.couplets[coupletIndex].text}
            </p>
          )}
          {selectedCantique.refrain && (
            <div className="projectionRefrain">
              <p><em>Refrain :</em></p>
              <p>{selectedCantique.refrain.text}</p>
            </div>
          )}
        </div>
      </div> {/* end projectionContainer */}

      {/* arrows moved outside overflow container */}
      <div className="projectionNav">
        <button
          onClick={prevCouplet}
          className="projectionArrow left"
          style={{ visibility: coupletIndex === 0 ? 'hidden' : 'visible' }}
        >
          &#9664;
        </button>
        <button
          onClick={nextCouplet}
          className="projectionArrow right"
          style={{ visibility: coupletIndex === selectedCantique.couplets.length - 1 ? 'hidden' : 'visible' }}
        >
          &#9654;
        </button>
      </div>
    </div>
  )
}

export default Projections